head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.key_dsicls_schdl_adm_dd = '';
scwin.key_bydd_seq = '';
scwin.key_integ_usr_id = '';
// 화면 리사이징

scwin.clickId;
scwin.gIsurCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_SDate.setValue($c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 1)); // 한달전 날짜
        edt_EDate.setValue(vCurDate);
        rdo_MKT_ID.setValue(js_market);
        panel_mkt.hide();

        // fn_Search();
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30008.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30008.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30008.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch_IR(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30008.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name btn_Input_onclick
 * @description 「입력」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Input_onclick = async function() {
    try {
        scwin.key_dsicls_schdl_adm_dd = '';
        scwin.key_bydd_seq = '';
        scwin.key_integ_usr_id = '';
        const options = {
            id: "ULDSTF30009",
            title: "상장적격성 실질심사 등록",
            type: "browserPopup",
            width: "480px",
            height: "390px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/dsclmgt/ULDSTF30009.gfm", options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30008.btn_Input_onclick" });
    }
};

/**
 * @method
 * @name icn_SCal_onclick
 * @description icn_SCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_SCal_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30008.icn_SCal_onclick" });
    }
};

/**
 * @method
 * @name icn_ECal_onclick
 * @description icn_ECal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_ECal_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30008.icn_ECal_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30008.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnFail
 * @description Grid On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnFail = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30008.dts_Grid_OnFail" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30008.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (rowcount <= 0) {
            dts_Grid.removeAll();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30008.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        scwin.gIsurCd = dts_Grid.getCellData(row, "ISUR_CD");
        if (colid === 'COM_ABBRV') {
            scwin.gIsurCd = dts_Grid.getCellData(row, "ISUR_CD");
            scwin.gIsurCd = scwin.gIsurCd.substring(0, 5);
            $c.stf.fn_PopupCorpInfo();
        } else if (colid === 'DISCLS_SCHDL_ADM_CONTN') {
            if (dts_Grid.getCellData(row, "DISCLS_SCHDL_ACT_STAT_CD") !== '0') {
                await $c.win.alert("공시일정상태가 미확정이 아닌경우 수정할 수 없습니다.");
            } else {
                const options = {
                    id: "ULDSTF30009",
                    title: "상장적격성실질심사 수정",
                    type: "browserPopup",
                    width: "480px",
                    height: "390px",
                    callbackFn: "scwin.popupCallback"
                };

                $c.win.openPopup("/dsclmgt/ULDSTF30009.gfm", options);
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30008.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30008.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30008.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30008.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30008.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30008.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30008.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30008.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (window.event.keyCode === 40) {
            // 아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            if (window.event.keyCode === 13) {
                $c.cm.fn_com_Confirm_set();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30008.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name rdo_MKT_ID_onselchange
 * @description rdo_MKT_ID onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_MKT_ID_onselchange = function() {
    // fn_SetCtrlByMktId();

};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&FROM_DATE=" + edt_SDate.getValue();
    url += "&TO_DATE=" + edt_EDate.getValue();
    url += "&ISUR_CD=" + txb_isur_cd.getValue();
    url += "&SCREN_ID=" + 'ULDSTF30008.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/DisclosureSchedule.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setId
 * @description set Id 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.setId = function(row) {
    scwin.key_dsicls_schdl_adm_dd = dts_Grid.getCellData(row, "DISCLS_SCHDL_ADM_DD");
    scwin.key_bydd_seq = dts_Grid.getCellData(row, "BYDD_SEQ");
    scwin.key_integ_usr_id = dts_Grid.getCellData(row, "INTEG_USR_ID");
};
